#include <Arduino.h>
const int RED_PIN = 5;       
const int GREEN_PIN = 6;     
const int BLUE_PIN = 7;       
const int BUTTON_RED = 2;     
const int BUTTON_GREEN = 3;   
const int BUTTON_BLUE = 4;    
int red = 0;
int green = 0;
int blue = 0;

void setup();
void loop();
void checkButton(int buttonPin, int* color);
void updateBarGraph(int level);
void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  pinMode(BLUE_PIN, OUTPUT);
  for (int i = 8; i <= 13; i++) {
    pinMode(i, OUTPUT);
    digitalWrite(i, LOW);
  }
  pinMode(44, OUTPUT);
  pinMode(45, OUTPUT);
  digitalWrite(44, LOW);
  digitalWrite(45, LOW);
  pinMode(BUTTON_RED, INPUT_PULLUP);
  pinMode(BUTTON_GREEN, INPUT_PULLUP);
  pinMode(BUTTON_BLUE, INPUT_PULLUP);
}
void loop() {
  checkButton(BUTTON_RED, &red);
  checkButton(BUTTON_GREEN, &green);
  checkButton(BUTTON_BLUE, &blue);
  analogWrite(RED_PIN, red);
  analogWrite(GREEN_PIN, green);
  analogWrite(BLUE_PIN, blue);
}
void checkButton(int buttonPin, int* color) {
  if (digitalRead(buttonPin) == LOW) {
    delay(50); 
    if (digitalRead(buttonPin) == LOW) {
      *color = (*color + 32) % 256; 
      updateBarGraph(*color / 32); 
      while (digitalRead(buttonPin) == LOW); 
    }
  }
}
void updateBarGraph(int level) {
  for (int i = 8; i <= 13; i++) {
    digitalWrite(i, (i - 8) < level ? HIGH : LOW);
  }
  digitalWrite(44, (6 < level) ? HIGH : LOW);
  digitalWrite(45, (7 < level) ? HIGH : LOW);
}
